<script setup lang="ts">
import {computed,onUnmounted,ref,shallowRef,watch} from 'vue'
import {onBeforeRouteLeave} from 'vue-router'
import { ElMessageBox } from 'element-plus'
import { feedback as ElMessage } from '../utils/feedback'
import {api} from '../api/client'
import {can,contextGeneration,session,switchingTenant} from '../stores/session'
import {contextTransitionGuards} from '../utils/contextTransitionGuard'
import {createSourceCollectionWorkspace,emptySourceCollectionState} from '../utils/inspectionSourceCollectionWorkspace'
import {readSourceCollectionPayload,sourceCollectionDiagnostics,type SourceCollectionContext} from '../utils/inspectionSourceCollections'
import {readInspectionSourceRevision,type InspectionSourceRevision} from '../utils/inspectionSourceRevision'
import {businessTimeZone,displayTime} from '../utils/display'
import ApiErrorNotice from '../components/ApiErrorNotice.vue'
import InspectionSourcePicker from '../components/InspectionSourcePicker.vue'
import InspectionWorksheetFacts from '../components/InspectionWorksheetFacts.vue'
const state=shallowRef(emptySourceCollectionState()),workspace=createSourceCollectionWorkspace(api,value=>{state.value=value})
let disposed=false
const pickerGeneration=ref(0),candidateDirty=ref(false)
const label=ref(''),sources=shallowRef<InspectionSourceRevision[]>([]),allowEmpty=ref(false),validation=ref(''),adding=ref(false),sourcePage=ref(0),expanded=ref('')
const permitted=computed(()=>Boolean(session.value?.mode==='remote_test'&&session.value.user.role==='padmin'&&can('inspection_source_collections:read')&&!switchingTenant.value)),writable=computed(()=>permitted.value&&can('inspection_source_collections:write')),canChoose=computed(()=>writable.value&&can('inspection_worksheets:read'))
const locked=computed(()=>!writable.value||Boolean(state.value.busy)||Boolean(state.value.attempt)||adding.value),selectedKeys=computed(()=>sources.value.map(s=>s.worksheet_id+'/'+s.version)),diagnostics=computed(()=>sourceCollectionDiagnostics(sources.value))
const contextKey=computed(()=>JSON.stringify([contextGeneration.value,session.value?.tenant.id,session.value?.user.id,session.value?.permission_version,session.value?.user.role,permitted.value,writable.value,canChoose.value]))
function context():SourceCollectionContext|null{const s=session.value;return s&&permitted.value?{tenantId:s.tenant.id,actorId:s.user.id,permissionVersion:s.permission_version,role:s.user.role,canRead:true,canWrite:writable.value}:null}
const dirty=computed(()=>state.value.attempt?.state!=='accepted'&&(candidateDirty.value||label.value!==''||sources.value.length>0||allowEmpty.value||state.value.attempt?.state==='rejected'))
const detailSources=computed(()=>state.value.selected?.sources.slice(sourcePage.value*10,sourcePage.value*10+10)??[])
function clearForm(){pickerGeneration.value++;candidateDirty.value=false;label.value='';sources.value=[];allowEmpty.value=false;validation.value='';adding.value=false}
watch(contextKey,()=>{workspace.reset(context());clearForm();sourcePage.value=0;expanded.value='';if(permitted.value)void workspace.list()},{immediate:true,flush:'sync'})
async function addSource(raw:InspectionSourceRevision){if(disposed||locked.value||!canChoose.value||sources.value.length>=1000)return false;const scope=context(),turn=contextKey.value;if(!scope)return false;adding.value=true;validation.value='';try{const source=await readInspectionSourceRevision(raw,scope,{worksheetId:raw.worksheet_id,version:raw.version});if(disposed||turn!==contextKey.value||!writable.value||state.value.attempt)return false;const key=source.worksheet_id+'/'+source.version;if(selectedKeys.value.includes(key)){validation.value='同一执行单修订不能重复加入；不同修订会分别保留';return false}sources.value=[...sources.value,source];allowEmpty.value=false;return true}catch{if(turn===contextKey.value)validation.value='来源核对失败，没有加入选择；请重新读取明确修订';return false}finally{if(!disposed&&turn===contextKey.value)adding.value=false}}
function removeSource(key:string){if(locked.value)return false;sources.value=sources.value.filter(s=>s.worksheet_id+'/'+s.version!==key);allowEmpty.value=false;return true}
function payload(){return {expected_version:0,label:label.value,sources:sources.value.map(s=>({worksheet_id:s.worksheet_id,version:s.version,expected_source_sha256:s.source_snapshot_sha256}))}}
async function save(){if(locked.value)return false;validation.value='';if(sources.value.length===0&&!allowEmpty.value){validation.value='请选择来源；如确实要保存空选择，请单独确认，空选择不代表零资产库存';return false}try{readSourceCollectionPayload(payload())}catch{validation.value='请填写非空且不超过200字符的标签，核对明确修订和来源摘要；未发送新请求';return false}const turn=contextKey.value,ok=await workspace.submit(payload());if(ok&&turn===contextKey.value)ElMessage.success('原保存回执已确认；完整正文请单独回读，仍不是正式报告');return ok}
async function retry(){const turn=contextKey.value,ok=await workspace.retry();if(ok&&turn===contextKey.value)ElMessage.success('已恢复完全相同原请求回执，没有另建集合');return ok}
function unlockRejected(){if(state.value.attempt?.state!=='rejected'||!workspace.begin())return false;validation.value='保留明确输入，原请求已拒绝；修改后需手动再次保存，不自动重选来源';return true}
async function discard(){if(!dirty.value)return true;try{await ElMessageBox.confirm('清除未确认保存的标签和明确来源选择？不会修改已保存集合。','保留未保存输入',{confirmButtonText:'确认清除输入',cancelButtonText:'保留输入',type:'warning'});return true}catch{return false}}
async function begin(){if(locked.value&&state.value.attempt?.state!=='accepted'||workspace.unresolved()||state.value.busy)return false;const turn=contextKey.value;if(!await discard()||turn!==contextKey.value||!workspace.begin())return false;clearForm();return true}
async function browse(next=false){sourcePage.value=0;expanded.value='';return workspace.list(next)}
async function select(id:string){sourcePage.value=0;expanded.value='';return workspace.select(id)}
function turnSources(delta:number){const count=state.value.selected?.sources.length??0,next=sourcePage.value+delta;if(next<0||next*10>=count)return;sourcePage.value=next;expanded.value=''}
async function mayLeave(){if(workspace.unresolved()){ElMessage.warning('先用原请求恢复结果，普通刷新不能确认是否已保存');return false}const turn=contextKey.value;return await discard()&&turn===contextKey.value}
onBeforeRouteLeave(mayLeave);const unregister=contextTransitionGuards.register(mayLeave)
function beforeUnload(event:BeforeUnloadEvent){if(workspace.unresolved()||dirty.value){event.preventDefault();event.returnValue=''}}
window.addEventListener('beforeunload',beforeUnload)
onUnmounted(()=>{disposed=true;unregister();workspace.dispose();clearForm();window.removeEventListener('beforeunload',beforeUnload)})
defineExpose({state,label,sources,allowEmpty,validation,payload,addSource,removeSource,save,retry,begin,unlockRejected,browse,select,hasUnresolved:workspace.unresolved})
</script>
<template>
 <section class="source-collection-page">
  <div class="page-heading"><div><span class="eyebrow">INSPECTION / EXPLICIT SOURCES</span><h1>巡检来源集合草稿</h1><p>当前租户：{{ session?.tenant.name }} · 明确修订 · 独立冻结 · 历史不重算</p></div></div>
  <el-alert type="warning" :closable="false" title="来源集合不是月报或季度报告">平台业务时区：{{ businessTimeZone }}。本集合没有选定报告周期；季度来源选取、归档政策、指标和报告模板版本仍未配置，租户资产总量未知。本页不自动取最新，不发布报告，不授予附件访问。</el-alert>
  <p v-if="!permitted" class="empty-panel">当前身份没有真实测试环境来源集合读取权限</p>
  <template v-else>
   <ol class="steps" aria-label="来源集合操作步骤"><li>1 · 指定修订并核对</li><li>2 · 明确加入与检查</li><li>3 · 保存原请求 / 单独回读</li></ol>
   <ApiErrorNotice :error="state.error" /><p v-if="state.busy||adding" role="status">{{ state.busy==='write'?'正在提交固定原请求，暂勿离开…':'正在只读核对，未显示旧详情…' }}</p>
   <section v-if="state.attempt" class="panel original-request" aria-live="polite"><h2>固定原保存请求</h2><p v-if="state.attempt.state==='uncertain'">结果未知。普通列表和详情即使看见集合，也不能确认这次原请求；拒绝重放不能证明之前没有写入。</p><p v-else-if="state.attempt.state==='accepted'">原保存回执已核对。它只含元数据，完整来源正文需单独读取和核对。</p><p v-else>原请求明确拒绝或派发前未通过校验。标签和来源选择保留，不自动替换。</p><div class="actions"><button v-if="state.attempt.state==='uncertain'" type="button" :disabled="Boolean(state.busy)" @click="retry">使用完全相同原请求重试</button><button v-if="state.attempt.state==='rejected'" type="button" :disabled="Boolean(state.busy)" @click="unlockRejected">保留输入并解锁</button><button v-if="state.receipt" type="button" :disabled="Boolean(state.busy)" @click="select(state.receipt.id)">回读这份集合正文</button><button v-if="state.attempt.state==='accepted'&&writable" type="button" :disabled="Boolean(state.busy)" @click="begin">明确开始另一份新集合</button></div></section>
   <section v-if="writable" class="panel collection-editor"><h2>明确来源选择</h2><InspectionSourcePicker v-if="canChoose" :key="pickerGeneration" :context="context()" :disabled="locked" :selected-keys="selectedKeys" @add="addSource" @dirty="candidateDirty=$event" /><p v-else class="warning">缺少执行单来源读取能力，不能从旧缓存补齐来源</p>
    <h3>2. 核对已选修订</h3><p>明确选择 {{ sources.length }} 个修订 · 涉及已选资产 {{ diagnostics.distinct_selected_assets }} 个（不是租户总资产）</p><p v-if="!sources.length" class="hint">尚未选择来源，不自动挑选第一项或最新版本</p><ul class="source-cards"><li v-for="s in sources" :key="s.worksheet_id+'/'+s.version"><div><strong>{{ s.asset_name }} · v{{ s.version }}</strong><p class="id">{{ s.worksheet_id }}</p><p>{{ s.archived?'所选修订已归档':'所选修订未归档' }} · {{ s.reported_performed_at===null?'巡检时间未填写':'有人工自述时间' }} · 未填 {{ s.summary.unanswered }} 项</p><details><summary>来源摘要</summary><p class="hash">{{ s.source_snapshot_sha256 }}</p></details></div><button type="button" :disabled="locked" :aria-label="`移除来源${s.worksheet_id}版本${s.version}`" @click="removeSource(s.worksheet_id+'/'+s.version)">移除选择</button></li></ul><p v-if="diagnostics.assets_with_multiple_sources.length" class="warning">存在同一资产的多份来源，不自动选最新、最差或未归档版本；它们会分别冻结。</p>
    <form v-form-feedback @submit.prevent="save"><fieldset :disabled="locked"><h3>3. 保存独立来源草稿</h3><label>集合标签<input v-model="label" aria-label="来源集合标签" autocomplete="off" required /></label><p class="hint">最多200个Unicode字符，已输入 {{ Array.from(label).length }} 个；保存后集合不可修改。</p><label v-if="sources.length===0" class="checkbox-label"><input v-model="allowEmpty" type="checkbox" aria-label="明确确认保存空来源选择" />明确保存空选择；不代表零资产库存、已完成巡检或可生成报告</label><button class="primary-button" type="submit" :disabled="sources.length===0&&!allowEmpty">保存明确来源集合草稿</button></fieldset><p v-if="validation" class="warning" role="alert">{{ validation }}</p></form>
    <button v-if="!state.attempt" type="button" :disabled="Boolean(state.busy)||adding" @click="begin">清除未保存选择</button>
   </section>
   <section v-if="state.receipt" class="panel receipt-panel"><h2>原保存回执 · 仅元数据</h2><p>{{ state.receipt.label }} · 明确来源 {{ state.receipt.source_count }} 个 · 版本1</p><p class="id">{{ state.receipt.id }}</p><p class="hint">已确认保存原请求，尚不能据此宣称已核对完整正文或完成正式报告。</p></section>
   <section class="panel collection-list"><div class="heading-row"><h2>已保存集合 · 元数据列表</h2><button type="button" :disabled="Boolean(state.busy)" @click="browse(false)">只读刷新第一页</button></div><p class="hint">列表不读取完整来源正文。刷新不会提交新集合，也不会确认未知原请求。</p><p v-if="!state.page" class="empty-panel">{{ state.busy==='read'?'正在读取，数量未知':state.error?'本次读取失败，旧列表不作成功结果':'尚未读取，数量未知' }}</p><template v-else><ul class="collection-cards"><li v-for="row in state.page.items" :key="row.id"><div><strong>{{ row.label }}</strong><p>明确来源 {{ row.source_count }} 个 · {{ displayTime(row.recorded_at) }}</p><p class="id">{{ row.id }}</p><span class="hint">未核验来源草稿 · 正文未读取 · 不可生成/未发布</span></div><button type="button" :disabled="Boolean(state.busy)" @click="select(row.id)">核对完整集合</button></li></ul><p v-if="!state.page.items.length" class="empty-panel">当前页没有可见集合；不代表租户无资产或已完成巡检</p><div class="actions"><span>本页 {{ state.page.items.length }} 条 · {{ state.paged?'续页':'第一页' }}</span><button v-if="state.paged" type="button" :disabled="Boolean(state.busy)" @click="browse(false)">返回第一页</button><button type="button" :disabled="Boolean(state.busy)||!state.page.has_more" @click="browse(true)">下一页集合</button></div></template></section>
   <section v-if="state.selected" class="panel collection-detail"><h2>完整来源已核对：{{ state.selected.label }}</h2><p class="id">{{ state.selected.id }}</p><p>模板 / 执行单 / 来源 / 清单 / 规范文档五层摘要一致；人工事实仍未核验，不是正式报告。</p><dl class="diagnostics"><div><dt>明确选择来源</dt><dd>{{ state.selected.source_count }}</dd></div><div><dt>涉及已选资产（非库存）</dt><dd>{{ state.selected.diagnostics.distinct_selected_assets }}</dd></div><div><dt>巡检时间未填的来源</dt><dd>{{ state.selected.diagnostics.unknown_inspection_time.length }}</dd></div><div><dt>有未填项的来源</dt><dd>{{ state.selected.diagnostics.incompletely_entered.length }}</dd></div><div><dt>选定已归档修订</dt><dd>{{ state.selected.diagnostics.archived_selected_revisions.length }}</dd></div><div><dt>同资产多来源分组</dt><dd>{{ state.selected.diagnostics.assets_with_multiple_sources.length }}</dd></div></dl><p class="warning">平台业务时区：{{ businessTimeZone }} · 报告周期：未选定，周期字段为空 · 来源选取/归档政策/指标/报告模板：未配置 · 租户资产总量：未知（null） · 正式生成：不可用 · 发布：未发布</p>
    <details><summary>核对集合记录与摘要</summary><p>记录人：{{ state.selected.created_by }} · {{ displayTime(state.selected.recorded_at) }}</p><p class="hash">清单 SHA256：{{ state.selected.source_manifest_sha256 }}</p><p class="hash">原文档 SHA256：{{ state.selected.document_sha256 }}</p></details><p v-if="!state.selected.sources.length" class="hint">这是一份明确的空选择，不能解释为零库存或已完成报告。</p>
    <article v-for="s in detailSources" :key="s.worksheet_id+'/'+s.version" class="frozen-source"><h3>{{ s.asset_name }} · 明确修订 v{{ s.version }}</h3><p class="id">{{ s.worksheet_id }}</p><p>{{ s.archived?'所选修订已归档':'所选修订未归档' }} · {{ s.action }} · 人工自述未核验</p><button type="button" :aria-expanded="expanded===s.worksheet_id+'/'+s.version" @click="expanded=expanded===s.worksheet_id+'/'+s.version?'':s.worksheet_id+'/'+s.version">{{ expanded===s.worksheet_id+'/'+s.version?'收起冻结来源内容':'展开冻结来源内容' }}</button><InspectionWorksheetFacts v-if="expanded===s.worksheet_id+'/'+s.version" :value="s" /></article>
    <div v-if="state.selected.sources.length" class="actions"><span>已核对全部 {{ state.selected.source_count }} 个来源，本页显示 {{ detailSources.length }} 个</span><button type="button" :disabled="sourcePage===0" @click="turnSources(-1)">上一组来源</button><button type="button" :disabled="(sourcePage+1)*10>=state.selected.source_count" @click="turnSources(1)">下一组来源</button></div>
   </section>
  </template>
 </section>
</template>
<style scoped>
.source-collection-page{min-width:0}.source-collection-page .panel{padding:20px;margin-top:18px;min-width:0}.source-collection-page h2{font-size:18px;margin:0 0 12px}.source-collection-page h3{font-size:16px;margin-top:20px}.source-collection-page p{overflow-wrap:anywhere}.steps{list-style:none;padding:0;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.steps li{padding:14px;background:#eaf1f8;border:1px solid #d3dfed;border-radius:9px;color:#314f70;line-height:1.5;overflow-wrap:anywhere}.source-collection-page button,.source-collection-page summary{min-height:44px;cursor:pointer}.source-collection-page button{padding:9px 14px;border:1px solid #cbd7e5;border-radius:8px;background:#fff;color:#294665;font:inherit}.source-collection-page button:disabled{opacity:.5;cursor:not-allowed}.source-collection-page .primary-button{background:#176bb5;color:#fff;border-color:#176bb5}.source-collection-page input:not([type=checkbox]){width:100%;min-height:44px;padding:10px;border:1px solid #bccbdc;border-radius:7px;box-sizing:border-box;font:inherit}.source-collection-page label{display:grid;gap:7px;min-width:0}.source-collection-page fieldset{border:0;padding:0;margin:0;min-width:0}.checkbox-label{display:flex!important;align-items:center;gap:8px;min-height:44px;margin-bottom:14px}.checkbox-label input{width:18px;height:18px;flex:0 0 auto}.source-cards,.collection-cards{padding:0;list-style:none}.source-cards>li,.collection-cards>li{display:flex;gap:16px;justify-content:space-between;align-items:flex-start;padding:16px 0;border-bottom:1px solid #dce5ef;min-width:0}.source-cards>li>div,.collection-cards>li>div{min-width:0}.source-cards strong,.collection-cards strong{overflow-wrap:anywhere}.source-cards button,.collection-cards button{flex-shrink:0}.id,.hash{font:12px monospace;line-height:1.6;overflow-wrap:anywhere}.warning{color:#80551c;white-space:pre-wrap}.hint,.empty-panel{color:#64758a;font-size:13px}.empty-panel{padding:16px}.actions,.heading-row{display:flex;align-items:center;flex-wrap:wrap;gap:10px;margin:12px 0}.heading-row{justify-content:space-between}.original-request{border-left:4px solid #cda24a}.receipt-panel{border-left:4px solid #6b93bc}.diagnostics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.diagnostics dt{font-size:12px;color:#64758a}.diagnostics dd{margin:6px 0;font-weight:600}.frozen-source{padding:14px 0;border-bottom:1px solid #dce5ef}@media(max-width:760px){.steps,.diagnostics{grid-template-columns:1fr}.source-collection-page .panel{padding:14px}.source-cards>li,.collection-cards>li{flex-direction:column}.source-cards button,.collection-cards button{width:100%}}
</style>
